local function QPSC_normalizeLanguage(rawLanguage)
    local raw = tostring(rawLanguage or "")
    local upper = string.upper(raw)

    if upper == "FR"
        or string.find(upper, "FRENCH", 1, true)
        or string.find(upper, "FRAN", 1, true) then
        return "FR"
    end

    if upper == "RU"
        or string.find(upper, "RUSSIAN", 1, true)
        or string.find(raw, "\208\160\209\131\209\129", 1, true) then
        return "RU"
    end

    return "EN"
end

function QPSC_I18N.getLanguageCode()
    local rawLanguage = ""

    local okTranslator, translatorLanguage = pcall(function()
        local language = Translator.getLanguage()
        if language then
            return tostring(language:name())
        end
        return ""
    end)

    if okTranslator and translatorLanguage and translatorLanguage ~= "" then
        rawLanguage = translatorLanguage
    else
        local okCore, coreLanguage = pcall(function()
            return tostring(getCore():getOptionLanguageName() or "")
        end)

        if okCore and coreLanguage then
            rawLanguage = coreLanguage
        end
    end

    return QPSC_normalizeLanguage(rawLanguage), rawLanguage
end

function QPSC_I18N.getText(key, ...)
    local languageCode =
        QPSC_I18N.getLanguageCode()

    local english =
        QPSC_I18N.Translations.EN or {}

    local translations =
        QPSC_I18N.Translations[languageCode]
        or english

    local value =
        translations[key]
        or english[key]
        or tostring(key)

    local result = tostring(value)
    local argumentCount = select("#", ...)

    for index = 1, argumentCount do
        local token = "%%" .. tostring(index)
        local replacement =
            tostring(select(index, ...))

        result = result:gsub(
            token,
            function()
                return replacement
            end
        )
    end

    return result
end

return QPSC_I18N
